def phase(h=None,label=None,detail='',bound=None,active=True):
 if h is not None and label is None: label=('≤' if bound=='le' else '')+str(h)+' min'
 return dict(headway=h,label=label or 'Not specified',detail=detail,bound=bound,active=active)
def off(detail='Not shown as a rail service in this planning horizon.'):
 return phase(None,'Later horizon',detail,active=False)
def p3(a,b=None,c=None):return {'2028':a,'2034':b or a,'2050':c or b or a}
def ref(page,detail='Table 1'):
 return dict(page=page,pdfPage=page+7,label=f'{detail}, p. {page}',url=P+f'#page={page+7}')
routes=[]
def add(id,name,kind,nodes,phases,group,read,do,source=37,geometry='rail',selector=None,via=None,offset=0,projects=None,notes='',conflict=None):
 routes.append(dict(id=id,name=name,kind=kind,nodes=nodes,phases=phases,group=group,why=read,action=do,source=ref(source),geometry=geometry,selector=selector,via=via,offset=offset,projects=projects or [],notes=notes,conflict=conflict))
