# Existing Amtrak long-distance inventory is a separate baseline, NOT a service
# goal for 2028/2034/2050. The phases below are display compatibility only: the UI
# retains the same inventory layer with every horizon and exports it separately.
def long_distance(id,name,nodes,frequency,short,full_route,pdf_page,end,continuation,why,offset=4,capital_ids=None,label_fraction=.47):
 detail=('One train per direction per day in the 2024 plan inventory; not a regular all-day headway.'
         if short=='Daily' else 'The 2024 plan inventory describes operation on three days per week; not daily service or a regular headway.')
 add(id,name,'longdistance',nodes,p3(phase(None,frequency,detail)),
     'Existing Amtrak',why,
     'Protect reliable national-network service and coordinate its connections with regional rail, local transit and the planned statewide network.',
     selector={'pass':name},offset=offset,
     notes='Existing service described by Appendix 3.1, not a new state-plan frequency target. Shown unchanged as context in all three horizon views, not a promise of future continuation. Frequencies and station context are plan-era, not a live timetable. Only selected California stops and the available rail-GIS extent are drawn; the full interstate alignment is not mapped. No additional near-term frequency is inferred.')
 r=routes[-1]
 r.update(baseline=True,geometryEnd=end,continuation=continuation,labelFraction=label_fraction,
          capitalIds=capital_ids or [],
          inventory={'year':2024,'frequency':frequency,'short':short,'fullRoute':full_route,'detail':detail},
          source={'page':pdf_page,'pdfPage':pdf_page,'document':'appendix',
                  'label':f'Existing-service inventory · Appendix 3.1 (PDF p. {pdf_page})',
                  'url':A+f'#page={pdf_page}'})
