# Make existing long-distance connections explicit at the selected city/hub anchors.
for c in cities:
 names=[r['name'] for r in routes if r.get('baseline') and c['id'] in r['nodes']]
 if names and not any(n in c['connections'] for n in names):
  c['connections']+='; '+', '.join(names)+' (2024 inventory)'
# Correct some source labels that are maps / prose rather than Table 1.
for r in routes:
 if r['source']['page'] in (35,36):r['source']['label']=f"Long-term service map / text, p. {r['source']['page']}"
 if r['id']=='hsr-valley-trunk':r['phases']['2050']['label']='≤15 min';r['phases']['2050']['detail']='Aggregate combined HSR trunk south of Madera; not every station pair.'
 if r['id']=='hsr-merced-madera':r['notes']='30-minute long-term branch in map p. 35; hourly initial Central Valley HSR in Table 1 p. 38. Conceptual geographic connection, not track design.'
 if r['id']=='bus-yosemite':r['source']=ref(35,'Long-term service map')
 if r['id']=='bus-sj-santacruz':r['source']=ref(35,'Long-term service map')
# High Desert / Vegas via list is ordered automatically by the geometry builder's dedicated trace.
from editorial import apply_routes
apply_routes(routes)
(ROOT/'data/network.json').write_text(json.dumps({'cities':cities,'routes':routes},indent=2))
rows=[]
for r in routes:
 if r.get('baseline'):continue
 for year,ph in r['phases'].items():
  rows.append(dict(corridor_id=r['id'],corridor=r['name'],service_type=r['kind'],horizon=year,active=ph['active'],headway_minutes=ph['headway'] or '',frequency=ph['label'],bound=ph['bound'] or '',detail=ph['detail'],source_page=r['source']['page'],source=r['source']['url'],geometry=r['geometry'],notes=r['notes'],source_discrepancy=r['conflict'] or ''))
